import os
from openai import OpenAI

def check_image_for_unsafe_content(image_url: str) -> dict:
    """
    Checks an image for unsafe content using OpenAI's GPT-4 Vision model.

    Args:
        image_url: The URL of the image to analyze.

    Returns:
        A dictionary indicating if the image is unsafe and providing a reason if so.
        Example: {"is_unsafe": True, "reason": "The image contains graphic violence."}
                 {"is_unsafe": False, "reason": "The image is safe."}
    """
    client = OpenAI(api_key=os.environ.get("OPENAI_API_KEY"))

    try:
        response = client.chat.completions.create(
            model="gpt-4o", # Using GPT-4o for its multimodal capabilities
            messages=[
                {
                    "role": "user",
                    "content": [
                        {"type": "text", "text": "Analyze this image for any unsafe, harmful, or policy-violating content such as violence, hate speech, self-harm, sexual content, or graphic imagery. If unsafe, briefly explain why. If safe, state that it is safe."},
                        {
                            "type": "image_url",
                            "image_url": {"url": image_url},
                        },
                    ],
                }
            ],
            max_tokens=150,
        )

        analysis_text = response.choices[0].message.content.strip()

        if "safe" in analysis_text.lower() and "not safe" not in analysis_text.lower():
            return {"is_unsafe": False, "reason": "The image is safe."}
        else:
            return {"is_unsafe": True, "reason": analysis_text}

    except Exception as e:
        return {"is_unsafe": True, "reason": f"An error occurred during analysis: {str(e)}"}
